import ee, math
ee.Initialize(project='earthsense-436113')

def get_cloud_stats(collection_id, geom, start, end):
    col = ee.ImageCollection(collection_id).filterDate(start, end).filterBounds(geom)
    size = col.size().getInfo()
    if size == 0:
        return {'images': 0, 'total': 0, 'cloud': 0, 'pct': None}
    img = col.mosaic()
    state = img.select('state_1km')
    # Cloud state bits 0-1: 0=clear, 1=cloudy, 2=mixed
    cloud_state = state.bitwiseAnd(3)
    cloud_mask = cloud_state.eq(1).Or(cloud_state.eq(2)).rename('cloud').toByte()
    total = state.reduceRegion(
        reducer=ee.Reducer.count(), geometry=geom, scale=1000, maxPixels=1e9
    ).get('state_1km').getInfo()
    cloud = cloud_mask.reduceRegion(
        reducer=ee.Reducer.sum(), geometry=geom, scale=1000, maxPixels=1e9
    ).get('cloud').getInfo()
    if total is None or cloud is None:
        return {'images': size, 'total': 0, 'cloud': None, 'pct': None}
    total = int(total)
    cloud = float(cloud)
    pct = (cloud / total * 100.0) if total > 0 else None
    return {'images': size, 'total': total, 'cloud': cloud, 'pct': pct}

try:
    # 1. Geometry & Time Definitions
    lakes_geom = ee.Geometry.Polygon(
