        print("C1")
    else:
        # 3. Processing & Validation
        terra_total = terra['total']
        aqua_total  = aqua['total']
        if (terra_total == 0) and (aqua_total == 0):
            print("No valid pixels after processing.")
            print("C2")
        else:
            # 4. Calculation Outputs
            def fmt_stats(label, s):
                if s['total'] == 0 or s['pct'] is None or s['cloud'] is None:
                    return f"{label} Pixels: 0"
                return f"{label} Pixels: {s['total']}, Cloud: {int(s['cloud'])}, Cloud%: {s['pct']:.2f}"
            print(fmt_stats("Terra", terra))
            print(fmt_stats("Aqua", aqua))

            # 5. Final Decision Logic
            def is_valid_number(x):
                return (x is not None) and (not (isinstance(x, float) and (math.isnan(x) or math.isinf(x))))
            if not (is_valid_number(terra['cloud']) or is_valid_number(aqua['cloud'])):
                print("C3")
            else:
                terra_cloudy = (is_valid_number(terra['cloud']) and terra['cloud'] > 0)
                aqua_cloudy  = (is_valid_number(aqua['cloud']) and aqua['cloud'] > 0)
                if terra_cloudy or aqua_cloudy:
                    print("A")
                else:
                    print("B")
